#!/usr/bin/env bash
# Homebrew end-to-end test of shell completions in generated formulas.
#
# 1. Fixture (testdata/e2e/completions, a shell script): bash and zsh
#    completions generated by the installed executable, fish shipped as a
#    file. Formula → brew style, audit --strict, install, the three files in
#    Homebrew's completion directories, completion in real bash, zsh and
#    fish, brew test, uninstall.
# 2. Hephaestus itself: v1.0.0 from the production tap's formula (read
#    only, pinned to a commit), then `brew upgrade` to a formula generated
#    from this checkout's hephaestus.yaml (version $HEPHAESTUS_E2E_VERSION,
#    local archives): the completion files appear, completion works in the
#    three shells, brew test, uninstall.
#
# Everything happens in throw-away taps and is removed on exit. It refuses to
# run when a formula named hephaestus or heph-comp is already installed, so a
# workstation's own installation is never touched; intended for disposable CI
# runners and containers. Set HEPHAESTUS_COMPLETION_SHELLS=1 to fail instead
# of skipping when bash, zsh or fish is missing.
set -euo pipefail
export LC_ALL=C

repo="$(cd "$(dirname "$0")/.." && pwd)"
harness="$repo/cmd/hephaestus/testdata/completion"
version="${HEPHAESTUS_E2E_VERSION:-1.0.1}"
# The production tap's formula of v1.0.0 (magicdrive/homebrew-tap, merged
# pull request #4): read only, from a fixed commit.
v100_formula="https://raw.githubusercontent.com/magicdrive/homebrew-tap/f700c89e31785cc76f8b8ffb72f82b2609cb2bd2/hephaestus.rb"
work="$(mktemp -d)"
tap="hephaestus-e2e/c$RANDOM$RANDOM"

export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_DEVELOPER=1 HOMEBREW_NO_ASK=1 \
  HOMEBREW_NO_INSTALL_CLEANUP=1 HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1 \
  HOMEBREW_NO_ANALYTICS=1 HOMEBREW_NO_ENV_HINTS=1

for f in hephaestus heph-comp; do
  if brew list --formula "$f" >/dev/null 2>&1; then
    echo "error: a formula named $f is already installed; run this test on a disposable machine" >&2
    exit 1
  fi
done

cleanup() {
  set +e
  brew uninstall --force "$tap/heph-comp" "$tap/hephaestus" >/dev/null 2>&1
  brew untap --force "$tap" >/dev/null 2>&1
  rm -rf "$work" "$repo/testdata/e2e/completions/dist"
}
trap cleanup EXIT

step() { printf '\n==> %s\n' "$*"; }
need_shell() {
  if command -v "$1" >/dev/null; then return 0; fi
  if [[ -n "${HEPHAESTUS_COMPLETION_SHELLS:-}" ]]; then echo "error: $1 is required" >&2; exit 1; fi
  echo "warning: $1 is not installed; its check is skipped" >&2
  return 1
}

prefix="$(brew --prefix)"
bash_dir="$prefix/etc/bash_completion.d"
zsh_dir="$prefix/share/zsh/site-functions"
fish_dir="$prefix/share/fish/vendor_completions.d"

# expect NAME WANT... < candidates: every WANT is among the candidates.
expect() {
  local name=$1; shift
  local got; got="$(cat)"
  for w in "$@"; do
    grep -qxF -- "$w" <<<"$got" || { echo "$name: missing $w in:"; echo "$got"; exit 1; }
  done
  echo "$name: ok ($*)"
}
bash_complete() { bash --norc --noprofile "$harness/complete.bash" "$@"; }
zsh_complete() { zsh -f "$harness/capture.zsh" "$zsh_dir" "$1" | sed '$d'; }
fish_complete() { fish --no-config -c "source $fish_dir/$1.fish; complete -C '$2'" | cut -f1; }

step "Build hephaestus"
(cd "$repo" && go build -trimpath -o "$work/hephaestus" .)
heph="$work/hephaestus"

brew tap-new --no-git "$tap" >/dev/null
formulae="$(brew --repository "$tap")/Formula"

# ---------------------------------------------------------------- fixture
step "Fixture heph-comp: archive, checksum, formula"
fixture="$repo/testdata/e2e/completions"
(cd "$fixture" && rm -rf dist && E2E_URL_BASE="file://$fixture/dist" HEPHAESTUS_ALLOW_FILE_URLS=1 \
  "$heph" run --stages archive,checksum,formula --tag "v1.0.0" --fresh)
cp "$fixture/dist/homebrew/heph-comp.rb" "$formulae/heph-comp.rb"
cat "$formulae/heph-comp.rb"
grep -qF 'generate_completions_from_executable(bin/"heph-comp", "completion", shells: [:bash, :zsh])' "$formulae/heph-comp.rb"
grep -qF 'fish_completion.install "completions/heph-comp.fish"' "$formulae/heph-comp.rb"

step "heph-comp: brew style, audit --strict, install"
brew style --formula "$tap/heph-comp"
brew audit --strict --formula "$tap/heph-comp"
brew install --formula "$tap/heph-comp"

step "heph-comp: completion files"
for f in "$bash_dir/heph-comp" "$zsh_dir/_heph-comp" "$fish_dir/heph-comp.fish"; do
  [[ -s "$f" ]] || { echo "missing $f"; exit 1; }
  echo "$f"
done

step "heph-comp: completion in real shells"
if need_shell bash; then
  # The generated script registers a word list: bash loads it and offers it.
  bash --norc --noprofile -c "source '$bash_dir/heph-comp' && complete -p heph-comp" | expect bash "complete -W 'alpha beta' heph-comp"
fi
if need_shell zsh; then zsh_complete 'heph-comp ' | expect zsh alpha beta; fi
if need_shell fish; then fish_complete heph-comp 'heph-comp ' | expect fish alpha beta; fi

step "heph-comp: brew test, uninstall"
brew test "$tap/heph-comp"
brew uninstall "$tap/heph-comp"
for f in "$bash_dir/heph-comp" "$zsh_dir/_heph-comp" "$fish_dir/heph-comp.fish"; do
  [[ ! -e "$f" ]] || { echo "left behind: $f"; exit 1; }
done

# ------------------------------------------------------------- hephaestus
step "hephaestus v1.0.0 from the production tap's formula (read only)"
curl -fsSL "$v100_formula" -o "$formulae/hephaestus.rb"
grep -q 'releases/download/v1.0.0/' "$formulae/hephaestus.rb"
if grep -q completion "$formulae/hephaestus.rb"; then echo "the v1.0.0 formula already has completions"; exit 1; fi
brew install --formula "$tap/hephaestus"
"$prefix/bin/hephaestus" version | grep -qx "hephaestus v1.0.0"
[[ ! -e "$zsh_dir/_hephaestus" && ! -e "$bash_dir/hephaestus" && ! -e "$fish_dir/hephaestus.fish" ]]
echo "v1.0.0 installed, no completion files"

step "hephaestus $version: formula from this checkout's hephaestus.yaml"
src="$work/src"
mkdir -p "$src"
(cd "$repo" && git ls-files -z | tar --null -T - -cf -) | tar -xf - -C "$src"
# Only the download URLs change: the archives are local.
sed -i.orig -e 's|^    skip_upload: auto$|    skip_upload: auto\n    url_template: "{{ .Env.E2E_URL_BASE }}/{{ .ArtifactName }}"|' "$src/hephaestus.yaml"
grep -q 'url_template' "$src/hephaestus.yaml"
(cd "$src" && E2E_URL_BASE="file://$src/dist" HEPHAESTUS_ALLOW_FILE_URLS=1 \
  "$heph" run --stages build,archive,checksum,formula --tag "v$version" --fresh)
cp "$src/dist/homebrew/hephaestus.rb" "$formulae/hephaestus.rb"
cat "$formulae/hephaestus.rb"
grep -qF 'generate_completions_from_executable(bin/"hephaestus", "completion")' "$formulae/hephaestus.rb"

step "hephaestus: brew style, audit --strict, upgrade 1.0.0 → $version"
brew style --formula "$tap/hephaestus"
brew audit --strict --formula "$tap/hephaestus"
brew upgrade --formula "$tap/hephaestus"
"$prefix/bin/hephaestus" version | grep -qx "hephaestus v$version"

step "hephaestus: completion files after the upgrade"
for f in "$bash_dir/hephaestus" "$zsh_dir/_hephaestus" "$fish_dir/hephaestus.fish"; do
  [[ -s "$f" ]] || { echo "missing $f"; exit 1; }
  echo "$f"
done
cmp <("$prefix/bin/hephaestus" completion bash) "$bash_dir/hephaestus"
cmp <("$prefix/bin/hephaestus" completion zsh) "$zsh_dir/_hephaestus"
cmp <("$prefix/bin/hephaestus" completion fish) "$fish_dir/hephaestus.fish"

step "hephaestus: completion in real shells, with the installed binary"
export PATH="$prefix/bin:$PATH"
if need_shell bash; then
  bash_complete "$bash_dir/hephaestus" hephaestus pre | expect bash preflight
  bash_complete "$bash_dir/hephaestus" hephaestus status --format= | expect bash --format=text --format=json
  bash_complete "$bash_dir/hephaestus" hephaestus completion "" | expect bash bash zsh fish
fi
if need_shell zsh; then
  zsh_complete 'hephaestus pre' | expect zsh preflight
  zsh_complete 'hephaestus status --format=' | expect zsh --format=text --format=json
  zsh_complete 'hephaestus run --stages build,a' | expect zsh build,archive
fi
if need_shell fish; then
  fish_complete hephaestus 'hephaestus pre' | expect fish preflight
  fish_complete hephaestus 'hephaestus init --template ' | expect fish go rust script prebuilt
fi

step "hephaestus: brew test, uninstall"
brew test "$tap/hephaestus"
brew uninstall "$tap/hephaestus"
for f in "$bash_dir/hephaestus" "$zsh_dir/_hephaestus" "$fish_dir/hephaestus.fish"; do
  [[ ! -e "$f" ]] || { echo "left behind: $f"; exit 1; }
done

echo
echo "Homebrew completion E2E passed (heph-comp; hephaestus 1.0.0 → $version)"
